/**
 * share-orchestrator.ts — Turbopack-safe wrapper around generateGanttShare.
 *
 * The problem: server.ts statically imports renderGantt/renderClientRundown from
 * GanttTemplate.tsx, which imports react-dom/server. When server.ts enters the
 * MCP route handler's import graph, Turbopack's build-time module-condition check
 * rejects the react-dom/server import with "not allowed in module condition".
 *
 * The fix: this wrapper re-exports the same GenerateGanttShare* types and delegates
 * to generateGanttShare at runtime via a standard import. Because this file does NOT
 * statically import GanttTemplate.tsx (or anything that does), it is safe to use in
 * MCP and Slack bot tool files. The actual render work still happens in server.ts at
 * runtime — we're only breaking the static analysis chain that Turbopack uses for
 * tree-shaking and module-condition validation.
 *
 * If server.ts is ever refactored to separate the render call into a standalone file
 * imported only by the CLI, this orchestrator can be deleted and MCP/Slack tools can
 * import server.ts directly.
 */

// Re-export types so callers don't need to import from server.ts at all.
export type { GenerateGanttShareInput, GenerateGanttShareResult } from "./server";

/**
 * Generate a signed share URL for a Gantt view.
 *
 * Identical contract to generateGanttShare in server.ts — this is a thin
 * delegation shim that exists solely to satisfy Turbopack's module-condition
 * analysis for MCP/Slack route handlers.
 */
export async function generateGanttShare(
  input: import("./server").GenerateGanttShareInput,
): Promise<import("./server").GenerateGanttShareResult> {
  // Dynamic import breaks Turbopack's static import-chain analysis. The module
  // resolves at runtime (Node.js, not the browser bundle) so react-dom/server
  // is valid in the execution environment.
  const { generateGanttShare: fn } = await import("./server");
  return fn(input);
}

