/**
 * share-orchestrator.ts — Turbopack-safe wrapper around generateGanttShare.
 *
 * The problem: server.ts statically imports renderGantt/renderClientRundown from
 * GanttTemplate.tsx, which imports react-dom/server. When server.ts enters the
 * MCP route handler's import graph via any static reference (including `import type`),
 * Turbopack's build-time module-condition check rejects the react-dom/server import.
 *
 * The fix: this module contains ZERO static references to server.ts or GanttTemplate.tsx.
 * It defines its own input/output types (structurally identical to those in server.ts),
 * and delegates to generateGanttShare at runtime via a fully dynamic import().
 *
 * Because Turbopack cannot trace through a string-literal dynamic import target at build
 * time, the react-dom/server import chain is invisible to the static analyzer. The render
 * work still executes in server.ts at runtime — we are only breaking the static build-
 * time chain, not changing execution semantics.
 *
 * If server.ts is ever refactored to isolate the render call (e.g. moving renderGantt
 * into a separate file that's only imported by the CLI/RSC side), this orchestrator can
 * be deleted and MCP/Slack tools can import server.ts directly.
 */

import type { Theme } from "./types";

/** Mirrors GenerateGanttShareInput in server.ts — kept in sync manually. */
export type GanttShareInput = {
  clientSlug: string;
  projectSlug?: string;
  theme: Theme;
  origin?: string;
  ttlDays?: number;
};

/** Mirrors GenerateGanttShareResult in server.ts — kept in sync manually. */
export type GanttShareResult = {
  shareUrl: string;
  expiresAt: string;
  summary: {
    kind: "client" | "project";
    clientName: string;
    projectName?: string;
    sectionCount?: number;
    rowCount?: number;
    severity: { critical: number; warn: number; info: number };
  };
};

/**
 * Generate a signed share URL for a Gantt view.
 *
 * Identical runtime contract to generateGanttShare in server.ts. This shim
 * exists solely to satisfy Turbopack's module-condition analysis for MCP and
 * Slack bot route handlers. All actual work is delegated to server.ts at runtime.
 */
export async function generateGanttShare(input: GanttShareInput): Promise<GanttShareResult> {
  // Fully dynamic import: Turbopack cannot statically trace this string at build
  // time, so the react-dom/server import chain in server.ts is invisible to the
  // build analyzer. At runtime this resolves to the real server.ts module.
  const mod = await import(
    /* webpackIgnore: true */
    "@/lib/runway/gantt/server"
  );
  return (mod.generateGanttShare as (input: GanttShareInput) => Promise<GanttShareResult>)(input);
}

