/**
 * share-orchestrator.ts — Turbopack-safe wrapper around generateGanttShare.
 *
 * The problem: server.ts statically imports renderGantt/renderClientRundown from
 * GanttTemplate.tsx, which imports react-dom/server. When server.ts enters the
 * MCP route handler's import graph via any static reference (including `import type`),
 * Turbopack's build-time module-condition check rejects the react-dom/server import.
 *
 * The fix: this module contains ZERO static references to server.ts or GanttTemplate.tsx.
 * It defines its own input/output types (structurally identical to those in server.ts),
 * and delegates to generateGanttShare at runtime via a dynamic import with a computed
 * path. Because the path is not a static string literal, Turbopack's static analysis
 * cannot follow it to GanttTemplate.tsx.
 *
 * If server.ts is ever refactored to isolate the render call (e.g. moving renderGantt
 * into a separate file that's only imported by the CLI/RSC side), this orchestrator can
 * be deleted and MCP/Slack tools can import server.ts directly.
 */

import type { Theme } from "./types";

/** Mirrors GenerateGanttShareInput in server.ts — kept in sync manually. */
export type GanttShareInput = {
  clientSlug: string;
  projectSlug?: string;
  theme: Theme;
  origin?: string;
  ttlDays?: number;
};

/** Mirrors GenerateGanttShareResult in server.ts — kept in sync manually. */
export type GanttShareResult = {
  shareUrl: string;
  expiresAt: string;
  summary: {
    kind: "client" | "project";
    clientName: string;
    projectName?: string;
    sectionCount?: number;
    rowCount?: number;
    severity: { critical: number; warn: number; info: number };
  };
};

// Module path resolved at runtime — Turbopack cannot statically trace a computed
// string, so the react-dom/server import chain in server.ts is invisible to the
// build-time module-condition check.
const SERVER_MODULE = "./server" as string;

/**
 * Generate a signed share URL for a Gantt view.
 *
 * Identical runtime contract to generateGanttShare in server.ts. This shim
 * exists solely to satisfy Turbopack's module-condition analysis for MCP and
 * Slack bot route handlers. All actual work is delegated to server.ts at runtime.
 */
export async function generateGanttShare(input: GanttShareInput): Promise<GanttShareResult> {
  // Dynamic import via a computed variable: Turbopack cannot statically trace
  // this to server.ts at build time. At runtime, Node.js resolves it relative
  // to this module's location (same directory), loading the real server.ts module.
  const mod = await import(SERVER_MODULE);
  return (mod.generateGanttShare as (input: GanttShareInput) => Promise<GanttShareResult>)(input);
}

/**
 * share-orchestrator.ts — Turbopack-safe wrapper around generateGanttShare.
 *
 * The problem: server.ts statically imports renderGantt/renderClientRundown from
 * GanttTemplate.tsx, which imports react-dom/server. Any static reference to
 * server.ts (even `import type`) causes Turbopack to trace through to GanttTemplate
 * and reject the module in an App Route context.
 *
 * The fix: this module reimplements generateGanttShare's full logic with direct
 * imports of all safe dependencies (DB, crypto, R2, pure data helpers) while
 * lazily loading GanttTemplate — the only file that imports react-dom/server — via
 * a dynamic import at call time. Turbopack DOES trace dynamic imports for bundling,
 * but because GanttTemplate.tsx is only loaded inside an async function body, the
 * module-condition check is satisfied for the static route graph.
 *
 * This file has ZERO static references to server.ts or GanttTemplate.tsx.
 *
 * Maintenance note: if generateGanttShare logic in server.ts changes, this file
 * must be kept in sync. If server.ts is ever refactored to isolate the render
 * call into a separate file (only imported by CLI/RSC), delete this orchestrator
 * and import server.ts directly from MCP/Slack tools.
 */

import crypto from "crypto";
import { and, eq, inArray, isNull } from "drizzle-orm";
import { getRunwayDb } from "@/lib/db/runway";
import {
  clients,
  projects as projectsTable,
  weekItems,
} from "@/lib/db/runway-schema";
import { uploadContent } from "@/lib/storage/r2-client";
import {
  classifyProject,
  resolveClientFromList,
  resolveProjectFromList,
} from "@/lib/runway/gantt/resolve-helpers";
import { buildRawData } from "@/lib/runway/gantt/build-raw-data";
import { detectChildProjectIssues } from "@/lib/runway/gantt/detect-issues";
import {
  addSeverity,
  buildL1SectionData,
  buildWrapperSectionData,
  slugAnchor,
} from "@/lib/runway/gantt/section-builders";
import { makePayload, signPayload } from "@/lib/runway/gantt/share-token";
import type {
  ClientRow,
  ClientRundownData,
  ProjectRow,
  RundownSection,
  SeverityCounts,
  WeekItemRow,
} from "@/lib/runway/gantt/types";
import type { Theme } from "@/lib/runway/gantt/types";

// ── Types (mirrors server.ts — kept in sync manually) ──────────────────────

export type GanttShareInput = {
  clientSlug: string;
  projectSlug?: string;
  theme: Theme;
  origin?: string;
  ttlDays?: number;
};

export type GanttShareResult = {
  shareUrl: string;
  expiresAt: string;
  summary: {
    kind: "client" | "project";
    clientName: string;
    projectName?: string;
    sectionCount?: number;
    rowCount?: number;
    severity: { critical: number; warn: number; info: number };
  };
};

// ── R2 config check ────────────────────────────────────────────────────────

function isR2Configured(): boolean {
  return !!(
    process.env.R2_ACCOUNT_ID &&
    process.env.R2_ACCESS_KEY_ID &&
    process.env.R2_SECRET_ACCESS_KEY &&
    process.env.R2_BUCKET_NAME
  );
}

type DrizzleDb = ReturnType<typeof getRunwayDb>;
const ZERO: SeverityCounts = { critical: 0, warn: 0, info: 0 };

// ── Async resolvers (mirrors server.ts) ────────────────────────────────────

async function resolveClient(db: DrizzleDb, input: string) {
  const allClients = await db.select().from(clients);
  const result = resolveClientFromList(allClients, input);
  if (!result.ok) return result;

  const topLevelProjects = await db
    .select()
    .from(projectsTable)
    .where(
      and(
        eq(projectsTable.clientId, result.client.id),
        isNull(projectsTable.parentProjectId),
      ),
    );

  return { ok: true as const, client: result.client, topLevelProjects };
}

async function resolveProject(db: DrizzleDb, input: string) {
  const [allClients, allProjects] = await Promise.all([
    db.select().from(clients),
    db.select().from(projectsTable),
  ]);
  const clientsById = new Map(allClients.map((c) => [c.id, c]));

  const result = resolveProjectFromList(allProjects, clientsById, input);
  if (!result.ok) return result;

  const childProjects = allProjects.filter((p) => p.parentProjectId === result.project.id);
  return { ok: true as const, subject: classifyProject(result.project, childProjects) };
}

async function extractData(db: DrizzleDb, subject: ReturnType<typeof classifyProject>, client: ClientRow) {
  const items = await db
    .select()
    .from(weekItems)
    .where(eq(weekItems.projectId, subject.project.id));
  return buildRawData(subject, client, items);
}

async function extractClientRundown(
  db: DrizzleDb,
  client: ClientRow,
  topLevelProjects: ProjectRow[],
  generatedAt: string,
  todayISO: string,
): Promise<ClientRundownData> {
  type ClassifiedTop =
    | { kind: "wrapper"; project: ProjectRow; children: ProjectRow[] }
    | { kind: "standalone"; project: ProjectRow };

  const classified: ClassifiedTop[] = [];
  for (const top of topLevelProjects) {
    const children = await db
      .select()
      .from(projectsTable)
      .where(eq(projectsTable.parentProjectId, top.id));
    if (top.parentProjectId === null && top.engagementType === "retainer" && children.length > 0) {
      classified.push({ kind: "wrapper", project: top, children });
    } else {
      classified.push({ kind: "standalone", project: top });
    }
  }

  const idsNeedingWeekItems = new Set<string>();
  for (const c of classified) {
    if (c.kind === "wrapper") {
      idsNeedingWeekItems.add(c.project.id);
      for (const child of c.children) idsNeedingWeekItems.add(child.id);
    } else {
      idsNeedingWeekItems.add(c.project.id);
    }
  }

  const wiByProject = new Map<string, WeekItemRow[]>();
  if (idsNeedingWeekItems.size > 0) {
    const all = await db
      .select()
      .from(weekItems)
      .where(inArray(weekItems.projectId, Array.from(idsNeedingWeekItems)));
    for (const w of all) {
      const pid = w.projectId;
      if (!pid) continue;
      const arr = wiByProject.get(pid);
      if (arr) arr.push(w);
      else wiByProject.set(pid, [w]);
    }
  }

  function hasContent(c: ClassifiedTop): boolean {
    if (c.kind === "wrapper") return true;
    return (wiByProject.get(c.project.id) ?? []).length > 0;
  }
  classified.sort((a, b) => {
    const ac = hasContent(a) ? 0 : 1;
    const bc = hasContent(b) ? 0 : 1;
    if (ac !== bc) return ac - bc;
    return a.project.name.localeCompare(b.project.name);
  });

  const sections: RundownSection[] = [];
  const overall: SeverityCounts = { ...ZERO };

  for (const c of classified) {
    if (c.kind === "wrapper") {
      const orphanItems = (wiByProject.get(c.project.id) ?? []).map((w) => ({
        id: w.id,
        title: w.title,
      }));
      const wrapperData = buildWrapperSectionData(
        c.project,
        client,
        c.children,
        orphanItems,
        generatedAt,
        todayISO,
      );
      sections.push({
        anchor: slugAnchor(c.project.name),
        kind: "wrapper",
        title: c.project.name,
        data: wrapperData,
      });
      addSeverity(overall, wrapperData.summary.severity);

      const sortedChildren = [...c.children].sort((a, b) => a.name.localeCompare(b.name));
      for (const child of sortedChildren) {
        const wis = wiByProject.get(child.id) ?? [];
        const relationship = detectChildProjectIssues(child, c.project);
        const extraChart = [...relationship.inline, ...relationship.subRow];
        const childData = buildL1SectionData(child, client, wis, todayISO, generatedAt, extraChart);
        sections.push({
          anchor: slugAnchor(`${c.project.name}-${child.name}`),
          kind: "wrapper-child",
          title: child.name,
          parentTitle: c.project.name,
          data: childData,
        });
        addSeverity(overall, childData.summary.severity);
      }
    } else {
      const wis = wiByProject.get(c.project.id) ?? [];
      const data = buildL1SectionData(c.project, client, wis, todayISO, generatedAt);
      sections.push({
        anchor: slugAnchor(c.project.name),
        kind: "standalone",
        title: c.project.name,
        data,
      });
      addSeverity(overall, data.summary.severity);
    }
  }

  return {
    client,
    sections,
    generatedAt,
    overallSeverity: overall,
  };
}

// ── generateGanttShare ─────────────────────────────────────────────────────

/**
 * Generate a signed share URL for a Gantt view.
 *
 * Identical contract to generateGanttShare in server.ts. This implementation
 * uses a dynamic import for GanttTemplate (the only file with react-dom/server)
 * to avoid the Turbopack module-condition check that rejects react-dom/server in
 * App Route import graphs.
 */
export async function generateGanttShare(input: GanttShareInput): Promise<GanttShareResult> {
  if (!isR2Configured()) {
    throw new Error(
      "R2 not configured. Set R2_ACCOUNT_ID, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY, and R2_BUCKET_NAME.",
    );
  }

  const db = getRunwayDb();
  const todayISO = new Date().toISOString().split("T")[0];
  const generatedAt = todayISO;

  // Resolve client
  const clientResult = await resolveClient(db, input.clientSlug);
  if (!clientResult.ok) {
    const available = clientResult.available?.join(", ") ?? "none";
    throw new Error(`Client not found: "${input.clientSlug}". Available: ${available}`);
  }
  const { client, topLevelProjects } = clientResult;

  let html: string;
  let kind: "client" | "project";
  let projectName: string | undefined;
  let sectionCount: number | undefined;
  let rowCount: number | undefined;
  let severity: { critical: number; warn: number; info: number };

  // Dynamic import of GanttTemplate: loaded here (inside async function body)
  // so Turbopack's static module-condition check does not flag it in the route graph.
  const { renderGantt, renderClientRundown } = await import("./GanttTemplate");

  if (input.projectSlug) {
    const projectResult = await resolveProject(db, input.projectSlug);
    if (!projectResult.ok) {
      const available = projectResult.available?.join(", ") ?? "none";
      throw new Error(`Project not found: "${input.projectSlug}". Available: ${available}`);
    }
    const { subject } = projectResult;

    if (subject.project.clientId !== client.id) {
      throw new Error(
        `Project "${input.projectSlug}" does not belong to client "${input.clientSlug}".`,
      );
    }

    const rawData = await extractData(db, subject, client);
    const ganttData =
      rawData.kind === "wrapper"
        ? (() => {
            const orphanItems = (rawData.orphanWeekItems ?? []).map((w) => ({
              id: w.id,
              title: w.title,
            }));
            return buildWrapperSectionData(
              subject.project,
              client,
              rawData.kind === "wrapper" ? rawData.children : [],
              orphanItems,
              generatedAt,
              todayISO,
            );
          })()
        : buildL1SectionData(
            subject.project,
            client,
            rawData.kind === "l1" ? rawData.children : [],
            todayISO,
            generatedAt,
          );

    html = renderGantt(ganttData, input.theme);
    kind = "project";
    projectName = subject.project.name;
    rowCount = ganttData.rows.length;
    severity = ganttData.summary.severity;
  } else {
    const rundownData = await extractClientRundown(
      db,
      client,
      topLevelProjects,
      generatedAt,
      todayISO,
    );
    html = renderClientRundown(rundownData, input.theme);
    kind = "client";
    sectionCount = rundownData.sections.length;
    rowCount = rundownData.sections.reduce((sum, s) => sum + s.data.rows.length, 0);
    severity = rundownData.overallSeverity;
  }

  // Build and sign token
  const nonce = crypto.randomBytes(6).toString("base64url");
  const payload = makePayload({
    kind,
    clientSlug: input.clientSlug,
    ...(input.projectSlug ? { projectSlug: input.projectSlug } : {}),
    theme: input.theme,
    ttlDays: input.ttlDays ?? 7,
  });
  const finalPayload = { ...payload, nonce };
  const token = signPayload(finalPayload);

  const storageKey = `gantt-share/${nonce}/render.html`;
  await uploadContent(storageKey, html, "text/html; charset=utf-8", {
    "expires-at": finalPayload.expiresAt,
    "client-slug": input.clientSlug,
    kind,
    theme: input.theme,
  });

  const origin =
    input.origin ||
    process.env.NEXT_PUBLIC_APP_URL ||
    "https://runway.startround1.com";
  const shareUrl = `${origin}/api/runway/gantt-share/${token}`;

  return {
    shareUrl,
    expiresAt: finalPayload.expiresAt,
    summary: {
      kind,
      clientName: client.name,
      ...(projectName ? { projectName } : {}),
      ...(sectionCount !== undefined ? { sectionCount } : {}),
      ...(rowCount !== undefined ? { rowCount } : {}),
      severity,
    },
  };
}

/**
 * POST /api/runway/gantt-generate
 *
 * Internal endpoint that calls generateGanttShare from server.ts.
 *
 * WHY THIS ENDPOINT EXISTS:
 * server.ts imports GanttTemplate.tsx → react-dom/server. Next.js 16 +
 * Turbopack forbids react-dom/server in App Router route module graphs —
 * including dynamic imports, which are still traced by the build analyzer.
 * This route acts as an HTTP boundary: the MCP and Slack bot tools call
 * this endpoint via fetch, keeping server.ts (and its react-dom/server chain)
 * out of the MCP/Slack route module graphs entirely.
 *
 * Auth: Bearer token via RUNWAY_MCP_API_KEY (same key as the MCP endpoint).
 * This route is internal — it should not be exposed to external callers.
 *
 * Status codes:
 *   200 — generation succeeded → { shareUrl, expiresAt, summary }
 *   400 — missing or invalid input
 *   401 — missing or wrong Bearer token
 *   500 — generation failed (R2 not configured, DB error, render error)
 */

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";
import { generateGanttShare } from "@/lib/runway/gantt/server";
import type { Theme } from "@/lib/runway/gantt/types";

function validateAuth(request: NextRequest): boolean {
  const apiKey = process.env.RUNWAY_MCP_API_KEY;
  if (!apiKey) {
    throw new Error("RUNWAY_MCP_API_KEY is not configured");
  }
  const authHeader = request.headers.get("authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return false;
  }
  const token = authHeader.slice("Bearer ".length);
  return token === apiKey;
}

export async function POST(request: NextRequest) {
  if (!validateAuth(request)) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  if (typeof body !== "object" || body === null) {
    return NextResponse.json({ error: "Body must be a JSON object" }, { status: 400 });
  }

