/**
 * share-orchestrator.ts — Turbopack-safe wrapper around generateGanttShare.
 *
 * The problem: server.ts imports GanttTemplate.tsx → react-dom/server.
 * Next.js 16 + Turbopack forbids react-dom/server in App Router route module
 * graphs — including dynamic imports, which are still traced by the build
 * analyzer for module-condition checking.
 *
 * The fix: this module calls /api/runway/gantt-generate via fetch, which is a
 * proper HTTP boundary. The MCP route handler's static module graph never
 * reaches server.ts or GanttTemplate.tsx. The gantt-generate route IS allowed
 * to import server.ts because it is a standalone App Route, not re-imported
 * into another route handler.
 *
 * Auth: Bearer token via RUNWAY_MCP_API_KEY (same key used by the MCP endpoint).
 * Origin: resolved from NEXT_PUBLIC_APP_URL → "http://localhost:3000" (dev fallback).
 *
 * Maintenance note: if the /api/runway/gantt-generate contract changes, update
 * this caller accordingly. The type definitions below mirror GenerateGanttShare*
 * in server.ts — keep them in sync.
 */

import type { Theme } from "./types";

/** Mirrors GenerateGanttShareInput in server.ts — kept in sync manually. */
export type GanttShareInput = {
  clientSlug: string;
  projectSlug?: string;
  theme: Theme;
  origin?: string;
  ttlDays?: number;
};

/** Mirrors GenerateGanttShareResult in server.ts — kept in sync manually. */
export type GanttShareResult = {
  shareUrl: string;
  expiresAt: string;
  summary: {
    kind: "client" | "project";
    clientName: string;
    projectName?: string;
    sectionCount?: number;
    rowCount?: number;
    severity: { critical: number; warn: number; info: number };
  };
};

/**
 * Generate a signed share URL for a Gantt view.
 *
 * Delegates to /api/runway/gantt-generate via an authenticated fetch call.
 * This HTTP boundary keeps GanttTemplate.tsx (react-dom/server) out of the
 * MCP and Slack bot route module graphs at build time.
 */
export async function generateGanttShare(input: GanttShareInput): Promise<GanttShareResult> {
  const apiKey = process.env.RUNWAY_MCP_API_KEY;
  if (!apiKey) {
    throw new Error("RUNWAY_MCP_API_KEY is not set — cannot call gantt-generate endpoint");
  }

  // Resolve origin: env var → dev fallback. The gantt-generate route is
  // co-located in the same Next.js app, so we can always reach it on localhost
  // in development. In production NEXT_PUBLIC_APP_URL must be set.
  const origin = process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000";
  const url = `${origin}/api/runway/gantt-generate`;

  const response = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      clientSlug: input.clientSlug,
      projectSlug: input.projectSlug,
      theme: input.theme,
      origin: input.origin,
      ttlDays: input.ttlDays,
    }),
  });

  if (!response.ok) {
    let message = `gantt-generate returned ${response.status}`;
    try {
      const body = (await response.json()) as { error?: string };
      if (body.error) message = body.error;
    } catch {
      // ignore parse failure
    }
    throw new Error(message);
  }

  return response.json() as Promise<GanttShareResult>;
}

